function msgCust(id){const c=D.c.find(x=>x.id==id);if(!c)return;const b=cbal(c),st=D.set.name,tp=[['تذكير بالرصيد',b>0?`مرحبًا ${c.n}،\nرصيدكم المستحق لدى ${st} هو ${f(b)} ج.م.\nنرجو التكرم بالسداد في أقرب وقت.\nشكرًا لتعاملكم معنا.`:`مرحبًا ${c.n}،\nلا يوجد لديكم رصيد مستحق لدى ${st}. شكرًا لتعاملكم معنا.`],['شكر',`مرحبًا ${c.n}،\nشكرًا لتعاملكم مع ${st}. يسعدنا خدمتكم دائمًا.`],['كشف الحساب',stText(c)],['رسالة فارغة','']];md();msgUI({name:c.n,phone:c.ph,text:tp[0][1],tpl:tp})}
function msgInv(id){const i=gi(id);if(!i)return;const c=D.c.find(x=>x.id==i.cid),tx=invText(i);md();msgUI({name:i.cust||'العميل',phone:c?c.ph:'',text:tx,tpl:[['الفاتورة',tx],['شكر',`شكرًا لتعاملكم مع ${D.set.name}. يسعدنا خدمتكم دائمًا.`],['رسالة فارغة','']]})}
