function rosterAdd(){D.set.ro=D.set.ro||{};D.set.ro[norm(ME.n)]={n:ME.n,r:ME.role,t:Date.now()};save()}
const chPeople=()=>Object.entries(D.set.ro||{}).filter(([k])=>k!=meKey()).map(([k,v])=>v);
function chatNotify(old){if(!ME)return;const nw=D.mg.filter(m=>!old.has(m.id)&&chVis(m)&&norm(m.fn)!=meKey());if(!nw.length)return;beep(true);tz('رسالة جديدة من '+nw[nw.length-1].fn+(nw.length>1?' (+'+(nw.length-1)+')':''));chatBadge()}
function rChat(){const keep=$('#chIn')?$('#chIn').value:'',ppl=chPeople(),last=c=>Math.max(0,...D.mg.filter(m=>m.ch==c).map(m=>m.t)),chans=[['all','الجميع','users'],...ppl.map(v=>[dmKey(v.n),v.n+(v.r=='admin'?' (مدير)':''),'user']).sort((a,b)=>last(b[0])-last(a[0]))];if(!chans.some(c=>c[0]==CH))CH='all';
$('#chBody').innerHTML=`<div class="bg-white rounded-2xl border border-beige-200 shadow-sm p-3 space-y-3"><div class="flex gap-2 overflow-x-auto no-scrollbar pb-1" role="tablist">${chans.map(([k,l,i])=>{const u=chUn(k),on=CH==k;return`<button role="tab" aria-selected="${on}" onclick="chOpen('${k}')" class="relative flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-semibold whitespace-nowrap min-h-[44px] ${on?'bg-gold-500 text-white':'bg-white border border-beige-200 text-gray-700'}">${ic(i,'w-4 h-4')}${e(l)}${u&&!on?`<span class="min-w-[20px] h-5 px-1 rounded-full bg-rose-500 text-white text-[11px] flex items-center justify-center">${u}</span>`:''}</button>`}).join('')}</div>${ppl.length?'':'<p class="text-xs text-gray-600">ستظهر هنا أسماء باقي المستخدمين بعد دخولهم إلى التطبيق لمراسلتهم بشكل خاص.</p>'}<div id="chMsgs" class="rounded-xl bg-beige-50 border border-beige-200 p-2 overflow-auto flex flex-col gap-2" style="height:calc(100dvh - 22rem);min-height:240px" aria-live="polite"></div><div class="flex items-end gap-2"><textarea id="chIn" rows="1" enterkeyhint="send" placeholder="اكتب رسالتك..." class="ip" style="min-height:44px;max-height:110px;padding-top:.6rem;flex:1;min-width:0" oninput="this.style.height='auto';this.style.height=Math.min(110,this.scrollHeight)+'px'" onkeydown="if(event.key=='Enter'&&!event.shiftKey){event.preventDefault();chatSend()}"></textarea><button class="bt bg1 shrink-0 flex items-center justify-center" style="min-width:48px;padding:0" onclick="chatSend()" aria-label="إرسال">${ic('send','w-5 h-5')}</button></div>${isA()?`<button class="text-xs text-rose-600 underline min-h-[40px]" onclick="chClear()">مسح هذه المحادثة</button>`:''}</div>`;$('#chIn').value=keep;chMsgs()}
