function applyTheme(){const m=thGet(),d=m=='dark'||(m=='auto'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.classList.toggle('dark',d);const cs=document.querySelector('meta[name=color-scheme]');if(cs)cs.content=d?'dark':'only light';const t=document.querySelector('meta[name=theme-color]');if(t)t.content=d?'#6e1218':'#890000'}
