function logoPick(el){const f=el.files[0];el.value='';if(!f)return;if(!f.type.startsWith('image/'))return tz('اختر ملف صورة');const u=URL.createObjectURL(f),im=new Image;im.onerror=()=>{URL.revokeObjectURL(u);tz('تعذر فتح الصورة')};im.onload=()=>{let k=Math.min(1,420/Math.max(im.width||420,im.height||420)),png=f.type=='image/png'||f.type=='image/webp'||f.type=='image/svg+xml',out='';for(let t=0;t<8;t++){const c=document.createElement('canvas');c.width=Math.max(1,Math.round((im.width||420)*k));c.height=Math.max(1,Math.round((im.height||420)*k));const g=c.getContext('2d');if(!png){g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height)}g.drawImage(im,0,0,c.width,c.height);out=png?c.toDataURL('image/png'):c.toDataURL('image/jpeg',.9);if(out.length*.75<=100*1024)break;k*=.8}URL.revokeObjectURL(u);if(out.length*.75>130*1024)return tz('الصورة كبيرة جدًا، اختر شعارًا أبسط');D.set.logo=out;D.set.logoOn=true;save();rSettings();tz('تم حفظ الشعار')};im.src=u}
