const CASH_TABS=['dashboard','store','pos','customers','invoices','ratings','settings','chat'],isA=()=>!!ME&&ME.role=='admin',canTab=t=>!ME||isA()||CASH_TABS.includes(t),canRet=()=>isA()||!!D.set.cashRet,mainTabs=()=>isA()?['dashboard','pos','products','invoices']:['dashboard','pos','invoices','customers'];
async function hp(role,pin){const t='obb|'+role+'|'+pin;try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(x){let h=5381;for(const c of t)h=((h<<5)+h+c.charCodeAt(0))>>>0;return'x'+h}}
const rnd8=()=>{const a=new Uint32Array(2);crypto.getRandomValues(a);return String(a[0]%10000).padStart(4,'0')+String(a[1]%10000).padStart(4,'0')},fmtRc=c=>c.slice(0,4)+'-'+c.slice(4),pinOk=v=>/^\d{4,8}$/.test(v);
function showLock(h){const l=$('#lock');l.innerHTML=`<div class="w-full max-w-sm bg-white text-darkslate rounded-3xl p-6 shadow-2xl space-y-3">${h}</div>`;l.classList.remove('hidden');l.classList.add('flex')}
const lockHead=(i,t,sub)=>`<div class="text-center"><div class="w-16 h-16 mx-auto rounded-full bg-gold-500 text-white flex items-center justify-center">${ic(i,'w-8 h-8')}</div><h2 class="text-xl font-extrabold mt-2">${t}</h2><p class="text-sm text-gray-600">${sub}</p></div>`,
pinIn=(id,l)=>`<label class="text-xs text-gray-600 block">${l}<input id="${id}" type="password" inputmode="numeric" maxlength="8" autocomplete="off" class="ip"></label>`,msgP='<p id="lgMsg" class="text-center text-sm text-rose-600 min-h-[20px]"></p>';
function bootLock(){if(booted)return;booted=true;let m=null;try{m=JSON.parse(sessionStorage.getItem('obb_me'))}catch(x){}if(m&&D.set.ph&&D.set.ph.admin&&(m.role=='admin'||D.set.ph.cash)){ME=m;afterLogin(true);return}lockUI()}
function lockUI(){md();D.set.ph&&D.set.ph.admin?loginUI():setupUI()}
function setLR(k){try{localStorage.setItem(K+'ln',$('#lgName').value);localStorage.setItem(K+'lr',k)}catch(x){}LR=k;loginUI()}
function loginUI(){let ln='';try{ln=localStorage.getItem(K+'ln')||'';LR=localStorage.getItem(K+'lr')||LR}catch(x){}
showLock(lockHead('lock',e(D.set.name),'سجّل الدخول للمتابعة')+`<div class="grid grid-cols-2 gap-2">${[['admin','المدير'],['cash','الكاشير']].map(([k,l])=>`<button onclick="setLR('${k}')" aria-pressed="${LR==k}" class="bt ${LR==k?'bg1':''}">${l}</button>`).join('')}</div><label class="text-xs text-gray-600 block">اسمك<input id="lgName" class="ip" value="${e(ln)}" placeholder="اكتب اسمك" autocomplete="off"></label>${pinIn('lgPin','الرمز السري')}<button class="bt bg1 w-full" onclick="doLogin()">دخول</button><button class="text-sm text-gray-600 underline w-full min-h-[36px]" onclick="forgotUI()">نسيت الرمز؟</button>${msgP}`);const p=$('#lgPin');p.onkeydown=ev=>{if(ev.key=='Enter')doLogin()}}
async function doLogin(){const m=t=>$('#lgMsg').textContent=t,now=Date.now();if(now<lockUntil)return m('انتظر '+Math.ceil((lockUntil-now)/1000)+' ثانية');const n=$('#lgName').value.trim(),pin=$('#lgPin').value,h=D.set.ph&&D.set.ph[LR];if(!n)return m('اكتب اسمك');if(!h)return m('لم يُعيّن المدير رمزًا للكاشير بعد');
if(await hp(LR,pin)!==h){tries++;$('#lgPin').value='';if(tries>=5){tries=0;lockUntil=Date.now()+30000;return m('محاولات كثيرة — انتظر 30 ثانية')}return m('الرمز غير صحيح')}
tries=0;ME={role:LR,n};try{sessionStorage.setItem('obb_me',JSON.stringify(ME));localStorage.setItem(K+'ln',n);localStorage.setItem(K+'lr',LR)}catch(x){}afterLogin()}
function setupUI(){showLock(lockHead('shield','إعداد حماية التطبيق','أنشئ حساب المدير. يمكنك إضافة رمز للكاشير الآن أو لاحقًا.')+`<label class="text-xs text-gray-600 block">اسم المدير<input id="suName" class="ip" placeholder="اكتب اسمك" autocomplete="off"></label>${pinIn('suPin','رمز المدير (4 إلى 8 أرقام)')}${pinIn('suPin2','تأكيد الرمز')}${pinIn('suCash','رمز الكاشير (اختياري)')}<button class="bt bg1 w-full" onclick="doSetup()">إنشاء وبدء الاستخدام</button>${msgP}`)}
async function doSetup(){const m=t=>$('#lgMsg').textContent=t,n=$('#suName').value.trim(),p=$('#suPin').value,p2=$('#suPin2').value,c=$('#suCash').value;if(!n)return m('اكتب اسمك');if(!pinOk(p))return m('الرمز من 4 إلى 8 أرقام');if(p!==p2)return m('الرمزان غير متطابقين');if(c&&!pinOk(c))return m('رمز الكاشير من 4 إلى 8 أرقام');
const rc=rnd8();D.set.ph={admin:await hp('admin',p),cash:c?await hp('cash',c):''};D.set.rc=await hp('rc',rc);ME={role:'admin',n};save();try{sessionStorage.setItem('obb_me',JSON.stringify(ME));localStorage.setItem(K+'ln',n);localStorage.setItem(K+'lr','admin')}catch(x){}
showLock(lockHead('shield','احفظ رمز الاسترجاع','إذا نسيت رمز المدير ستحتاج هذا الرمز. يظهر هنا مرة واحدة فقط — اكتبه في مكان آمن.')+`<div class="text-center text-3xl font-extrabold tracking-widest bg-gold-100 rounded-2xl py-4" dir="ltr">${fmtRc(rc)}</div><button class="bt bg1 w-full" onclick="afterLogin()">حفظته، متابعة</button>`)}
function forgotUI(){showLock(lockHead('lock','استرجاع رمز المدير','اكتب رمز الاسترجاع الذي حصلت عليه عند الإعداد.')+`<label class="text-xs text-gray-600 block">رمز الاسترجاع<input id="fgCode" class="ip" inputmode="numeric" dir="ltr" placeholder="0000-0000" autocomplete="off"></label><label class="text-xs text-gray-600 block">اسمك<input id="fgName" class="ip" autocomplete="off"></label>${pinIn('fgPin','رمز المدير الجديد')}<button class="bt bg1 w-full" onclick="doRecover()">استرجاع والدخول</button><button class="text-sm text-gray-600 underline w-full min-h-[36px]" onclick="loginUI()">رجوع</button>${msgP}`)}
async function doRecover(){const m=t=>$('#lgMsg').textContent=t,code=$('#fgCode').value.replace(/\D/g,''),n=$('#fgName').value.trim(),p=$('#fgPin').value;if(!n)return m('اكتب اسمك');if(!pinOk(p))return m('الرمز الجديد من 4 إلى 8 أرقام');if(!D.set.rc||await hp('rc',code)!==D.set.rc)return m('رمز الاسترجاع غير صحيح');
D.set.ph={...D.set.ph,admin:await hp('admin',p)};save();ME={role:'admin',n};try{sessionStorage.setItem('obb_me',JSON.stringify(ME))}catch(x){}afterLogin()}
