const dleft=exp=>Math.ceil((new Date(exp+'T00:00:00')-new Date(ld(new Date())+'T00:00:00'))/864e5),bsum=p=>sum(p.bt||[],b=>b.q),expDays=()=>D.set.expDays||30,
chip=(l,on,fn)=>`<button onclick="${fn}" class="px-4 py-2 rounded-full text-sm font-semibold whitespace-nowrap min-h-[44px] ${on?'bg-gold-500 text-white':'bg-white border border-beige-200 text-gray-700'}">${l}</button>`;
function fixBt(p){if(!p.bt||!p.bt.length)return;let ex=bsum(p)-p.q;if(ex>0){p.bt.sort((a,b)=>a.exp<b.exp?-1:1);for(const b of p.bt){if(ex<=0)break;const t=Math.min(b.q,ex);b.q-=t;ex-=t}}p.bt=p.bt.filter(b=>b.q>0)}
function consume(p,qty){if(!p.bt)return;p.bt.sort((a,b)=>a.exp<b.exp?-1:1);for(const b of p.bt){if(qty<=0)break;const t=Math.min(b.q,qty);b.q-=t;qty-=t}p.bt=p.bt.filter(b=>b.q>0)}
const expAll=()=>{const a=[];D.p.forEach(p=>(p.bt||[]).forEach(b=>a.push({p,b,d:dleft(b.exp)})));return a.sort((x,y)=>x.d-y.d)},expList=()=>expAll().filter(x=>x.d<=expDays());
function rExpiry(){const l=expList();$('#expBox').innerHTML=l.length?`<table class="tbl"><tr><th>المنتج</th><th>الكمية</th><th>تاريخ الانتهاء</th><th>الحالة</th><th></th></tr>${l.map(x=>`<tr class="${x.d<0?'bg-rose-50':'bg-amber-50'}"><td>${e(x.p.n)}</td><td>${x.b.q}</td><td>${x.b.exp}</td><td><b class="${x.d<0?'text-rose-700':'text-amber-700'}">${x.d<0?'منتهية منذ '+(-x.d)+' يوم':'متبقي '+x.d+' يوم'}</b></td><td><button class="bt" onclick="batchUI('${x.p.id}')">الدفعات</button></td></tr>`).join('')}</table>`:'<p class="text-sm text-emerald-700 font-semibold">لا توجد دفعات منتهية أو قريبة من الانتهاء</p>'}
function batchUI(pid){const p=gp(pid),bt=(p.bt||[]).slice().sort((a,b)=>a.exp<b.exp?-1:1),free=Math.max(0,p.q-bsum(p));md(`<h3 class="font-bold mb-1">الصلاحية — ${e(p.n)}</h3><p class="text-xs text-gray-600 mb-3">المخزون ${p.q} — منها ${bsum(p)} بتاريخ صلاحية و${free} بدون تاريخ. يُباع الأقرب انتهاءً أولًا.</p>${bt.length?`<div class="space-y-1 mb-3">${bt.map(b=>{const d=dleft(b.exp);return`<div class="flex items-center justify-between gap-2 p-2 rounded-xl border ${d<0?'border-rose-300 bg-rose-50':d<=expDays()?'border-amber-300 bg-amber-50':'border-beige-200'}"><div><b>${b.q}</b> قطعة — ${b.exp}<div class="text-xs ${d<0?'text-rose-700':'text-gray-600'}">${d<0?'منتهية منذ '+(-d)+' يوم':'متبقي '+d+' يوم'}</div></div><button class="text-rose-600 p-1" onclick="batchDel('${pid}','${b.exp}')" aria-label="حذف الدفعة">${ic('x','w-4 h-4')}</button></div>`}).join('')}</div>`:'<p class="text-sm text-gray-500 mb-3">لا توجد دفعات مسجلة</p>'}<div class="grid grid-cols-2 gap-3"><label class="text-xs text-gray-600">الكمية<input id="bq" type="number" inputmode="numeric" min="1" class="ip"></label><label class="text-xs text-gray-600">تاريخ الصلاحية<input id="bd" type="date" class="ip"></label></div><label class="flex items-center gap-3 min-h-[44px] text-sm font-semibold"><input id="bex" type="checkbox" checked class="w-5 h-5">الكمية موجودة بالفعل في المخزون (لا تزِد المخزون)</label><div class="flex gap-2 mt-2"><button class="bt bg1 flex-1" onclick="batchAdd('${pid}')">إضافة دفعة</button><button class="bt" onclick="md()">إغلاق</button></div>`)}
function batchAdd(pid){const p=gp(pid),q=Math.floor(+$('#bq').value||0),d=$('#bd').value,ex=$('#bex').checked;if(!(q>0)||!d)return tz('اكتب الكمية وتاريخ الصلاحية');if(ex&&q>p.q-bsum(p))return tz('الكمية أكبر من المخزون غير المؤرَّخ ('+(p.q-bsum(p))+')');if(!ex)p.q+=q;p.bt=p.bt||[];const b=p.bt.find(x=>x.exp==d);b?b.q+=q:p.bt.push({q,exp:d});save();batchUI(pid);rInv();tz('تمت إضافة الدفعة')}
