function se(id,pos){const s0=D.sp.find(x=>x.id==id);fm('مورد',[['n','اسم المورد','text',1],['ph','الهاتف'],['prev','رصيد سابق (مستحق له)','number']],s0||{},o=>{if(!o.n)return tz('اكتب اسم المورد');const d={n:o.n,ph:o.ph,prev:+o.prev||0};let nid=id;if(s0)Object.assign(s0,d);else{nid=U();D.sp.push({id:nid,...d,t:Date.now()})}save();if(pos){PU.sid=nid;puNew()}else rPurchases()})}
