const EL=['0001101','0011001','0010011','0111101','0100011','0110001','0101111','0111011','0110111','0001011'],EG=['0100111','0110011','0011011','0100001','0011101','0111001','0000101','0010001','0001001','0010111'],ER=['1110010','1100110','1101100','1000010','1011100','1001110','1010000','1000100','1001000','1110100'],EP=['LLLLLL','LLGLGG','LLGGLG','LLGGGL','LGLLGG','LGGLLG','LGGGLL','LGLGLG','LGLGGL','LGGLGL'];
const C39={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn','K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn','U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn','-':'nwnnnnwnw','.':'wwnnnnwnn',' ':'nwwnnnwnn','$':'nwnwnwnnn','/':'nwnwnnnwn','+':'nwnnnwnwn','%':'nnnwnwnwn','*':'nwnnwnwnn'};
const ean13chk=d=>{let t=0;for(let i=0;i<12;i++)t+=(+d[i])*(i%2?3:1);return(10-t%10)%10},ean8chk=d=>{let t=0;for(let i=0;i<7;i++)t+=(+d[i])*(i%2?1:3);return(10-t%10)%10};
function genEAN(){const ex=new Set(D.p.map(p=>p.bc));let c;do{const d='2'+String(Math.floor(Math.random()*1e11)).padStart(11,'0');c=d+ean13chk(d)}while(ex.has(c));return c}
function bcBits(code){code=String(code||'').trim();let m=null,kind='';
if(/^\d{13}$/.test(code)&&ean13chk(code)==+code[12]){kind='EAN-13';const par=EP[+code[0]];m='101';for(let i=1;i<7;i++)m+=(par[i-1]=='L'?EL:EG)[+code[i]];m+='01010';for(let i=7;i<13;i++)m+=ER[+code[i]];m+='101'}
else if(/^\d{8}$/.test(code)&&ean8chk(code)==+code[7]){kind='EAN-8';m='101';for(let i=0;i<4;i++)m+=EL[+code[i]];m+='01010';for(let i=4;i<8;i++)m+=ER[+code[i]];m+='101'}
else{const c=code.toUpperCase();if(c&&[...c].every(ch=>C39[ch]&&ch!='*')){kind='Code 39';m='';for(const ch of '*'+c+'*'){[...C39[ch]].forEach((x,i)=>{m+=(i%2?'0':'1').repeat(x=='w'?3:1)});m+='0'}m=m.slice(0,-1)}}
return m?{kind,m}:null}
function bcSvg(code,h=40){const b=bcBits(code);if(!b)return'';const mg=10,W=b.m.length+mg*2;let r='';for(let i=0;i<b.m.length;){if(b.m[i]=='1'){let j=i;while(j<b.m.length&&b.m[j]=='1')j++;r+=`<rect x="${mg+i}" y="0" width="${j-i}" height="${h}"/>`;i=j}else i++}return`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${h}" preserveAspectRatio="none" shape-rendering="crispEdges" style="width:100%;height:100%"><rect width="${W}" height="${h}" fill="#fff"/><g fill="#000">${r}</g></svg>`}
const LSZ={'50x30':[50,30],'40x25':[40,25],'58x40':[58,40],a4:[70,37]};let LB={sel:{},size:'50x30',price:true,store:false,q:''};
function lblHtml(p,o){const bc=p.bc||'',[w,h]=LSZ[o.size];return`<div class="lbl" style="width:${w}mm;height:${h}mm;padding:1mm">${o.store?`<div style="font-size:6px;font-weight:700;line-height:1">${e(D.set.name)}</div>`:''}<div style="font-size:${h<28?8:9}px;font-weight:700;line-height:1.1;max-height:2.3em;overflow:hidden;width:100%">${e(p.n)}</div><div style="width:92%;height:${Math.round(h*.36)}mm">${bcSvg(bc)||'<div style="font-size:8px">لا يوجد باركود</div>'}</div><div style="font-size:7px;letter-spacing:1px" dir="ltr">${e(bc)}</div>${o.price?`<div style="font-size:11px;font-weight:800">${f(p.sell)} ج.م</div>`:''}</div>`}
