function rMode(){$('#modeBar').innerHTML=[['retail','بيع تجزئة'],['whs','بيع جملة']].map(([k,l])=>`<button onclick="setMode('${k}')" aria-pressed="${pmode==k}" class="bt flex-1 min-w-0 whitespace-nowrap overflow-hidden ${pmode==k?'bg1':''}" style="padding:0 .5rem;text-overflow:ellipsis">${l}</button>`).join('')}
