function posRes(){const q=norm($('#posQ').value||'').trim().replace(/^\d+\s*[*x×]\s*/,''),l=(()=>{const m=D.p.filter(p=>(!pcp||p.cat==pcp)&&pm(p,q));if(!q)return m.slice(0,60);return m.map(p=>[rankP(p,q),p]).sort((a,b)=>a[0]-b[0]).slice(0,60).map(x=>x[1])})(),el=$('#posRes');el.className=pview=='grid'?'grid grid-cols-2 sm:grid-cols-3 gap-3':'grid grid-cols-1 gap-2 sm:grid-cols-2';$('#viewBtn').innerHTML=ic(pview=='grid'?'list':'grid','w-5 h-5');el.innerHTML=l.length?l.map(pview=='grid'?card:prow).join(''):'<p class="col-span-full text-center text-gray-500 py-8">لا توجد منتجات مطابقة</p>'}
function posScan(v){v=String(v||'').trim();if(!v)return;let n=1;const m0=norm(v).match(/^(\d+)\s*[*x×]\s*(.+)$/);if(m0){n=+m0[1]||1;v=v.replace(/^[^*x×X]*[*x×X]\s*/,'').trim()}const m=D.p.filter(p=>pm(p,v)),p=D.p.find(x=>bcEq(x,v))||(m.length==1&&m[0]);if(!p){beep(false);return tz(m.length>1?'يوجد '+m.length+' منتجات مطابقة — اختر من القائمة':'لا يوجد منتج مطابق')}addCart(p.id,n);$('#posQ').value='';posRes()}
