function askQty(id){const i=cart.findIndex(l=>l.pid==id);if(i<0)return;ask('اكتب الكمية',cart[i].qty,v=>{v=Math.floor(+v);const p=gp(id);if(!(v>=1))cart.splice(i,1);else{cart[i].qty=0&&v>p.q?p.q:v;if(0&&v>p.q)tz('المتاح '+p.q)}rCart()})}
