function qc(i,el){const l=cart[i],p=gp(l.pid);let v=Math.floor(+el.value);if(!(v>=1))return;if(0&&v>p.q){v=p.q;el.value=v;tz('المتاح '+p.q)}l.qty=v;$('#lt'+i).textContent=f(l.price*v);pcart();tot()}
