addEventListener('keydown',ev=>{if(tab!='pos'||$('#mdl').innerHTML)return;if(ev.key=='F2'){ev.preventDefault();$('#posQ').focus()}else if(ev.key=='F8'){ev.preventDefault();$('#pPaid').focus()}else if(ev.key=='F9'||(ev.ctrlKey&&ev.key=='Enter')){ev.preventDefault();checkout(1)}});
