function rCart(){pcart();if(tab=='pos')posRes();if(tab=='store')rStore();const ro=isA()||D.set.cashPrice!==false?'':'readonly',nk="if(event.key=='Enter'){event.preventDefault();$('#posQ').focus()}";$('#cartLines').innerHTML=cart.length?cart.map((l,i)=>`<div class="py-2 border-b border-beige-100 space-y-2"><div class="flex items-start gap-2"><div class="flex-1 min-w-0 font-semibold text-sm leading-snug">${e(l.n)}</div><b id="lt${i}" class="text-sm whitespace-nowrap pt-0.5">${f(l.price*l.qty)}</b><button onclick="cart.splice(${i},1);rCart()" class="text-rose-600" aria-label="حذف">${ic('x','w-4 h-4')}</button></div><div class="flex flex-wrap items-center justify-between gap-2"><label class="text-xs text-gray-600 flex items-center gap-1 shrink-0"><span class="whitespace-nowrap">السعر</span><input type="number" inputmode="decimal" min="0" step="any" value="${l.price}" oninput="pc(${i},this)" onkeydown="${nk}" aria-label="سعر ${e(l.n)}" ${ro} class="ip" style="width:4.6rem;min-height:40px;padding:.2rem .4rem${l.cost&&l.price<l.cost?';border-color:#e11d48':''}"></label><div class="flex items-center gap-1 shrink-0"><button onclick="cq(${i},-1)" class="w-9 h-10 rounded-lg bg-beige-100 font-bold" aria-label="إنقاص">${ic('minus','w-4 h-4 mx-auto')}</button><input type="number" inputmode="numeric" min="1" step="1" value="${l.qty}" onfocus="this.select()" oninput="qc(${i},this)" onchange="qd(${i},this)" onkeydown="${nk}" aria-label="الكمية" class="ip" style="width:3.2rem;min-height:40px;padding:.2rem;text-align:center"><button onclick="cq(${i},1)" class="w-9 h-10 rounded-lg bg-beige-100 font-bold" aria-label="زيادة">${ic('plus','w-4 h-4 mx-auto')}</button></div></div></div>`).join(''):'<p class="text-gray-500 text-sm py-6 text-center">السلة فارغة — امسح باركود أو اضغط على منتج</p>';tot()}
function sums(){const s=sum(cart,l=>l.price*l.qty),d=dpct?Math.min(s,Math.round(s*(+$('#pDisc').value||0))/100):(+$('#pDisc').value||0),n=Math.max(0,s-d),pd=$('#pPaid').value===''?n:+$('#pPaid').value;return{s,d,n,pd}}
