var XPF={effra:'EffraXP,Arial,Tahoma,\'Noto Sans Arabic\',sans-serif',arial:'Arial,Tahoma,\'Noto Sans Arabic\',\'Segoe UI\',sans-serif',tahoma:'Tahoma,Arial,\'Noto Sans Arabic\',sans-serif',cairo:'Cairo,Tahoma,sans-serif'};
