function wsR(){const t=$('#wsTbl');if(!t)return;t.innerHTML=WS.length?WS.map((l,i)=>`<div class="grid items-center px-2 py-2 border-b border-beige-200" style="grid-template-columns:1fr 4rem 6.6rem 6.2rem;min-height:48px"><div class="px-1 font-bold leading-snug" style="font-size:13px;overflow-wrap:anywhere">${e(l.n)}</div><input type="number" inputmode="decimal" min="0" value="${l.price}" class="ip text-center" style="min-height:34px;padding:0 .2rem;font-weight:700;font-size:14px" onchange="wsPrice(${i},this.value)"><div class="flex items-center justify-center"><button class="w-6 text-gold-700 text-xl font-bold" onclick="wsInc(${i},-1)" aria-label="إنقاص">−</button><input type="number" inputmode="decimal" min="0" step="any" value="${l.qty}" class="ip text-center" style="min-height:34px;width:2.9rem;padding:0 .1rem;font-weight:700;font-size:14px" onchange="wsQty(${i},this.value)"><button class="w-6 text-gold-700 text-xl font-bold" onclick="wsInc(${i},1)" aria-label="زيادة">+</button></div><div class="flex items-center justify-between gap-1"><span id="wsL${i}" class="font-bold text-center flex-1" style="font-size:${wsFs(wsF2(l.price*l.qty))};white-space:nowrap;min-width:0">${wsF2(l.price*l.qty)} ج.م</span><button class="text-rose-600 font-bold shrink-0" style="font-size:14px;width:22px;min-width:22px;min-height:30px;padding:0" onclick="WS.splice(${i},1);wsR()" aria-label="حذف">✕</button></div></div>`).join(''):'<div class="text-center text-gray-500 py-16">لم تُضف منتجات بعد</div>';wsT()}
