async function wsCam(){const b=$('#wsCamBox');if(!b.classList.contains('hidden')){WCS?.getTracks().forEach(t=>t.stop());WCS=null;b.classList.add('hidden');return}b.classList.remove('hidden');if(!(navigator.mediaDevices&&'BarcodeDetector' in window))return tz('مسح الكاميرا غير مدعوم هنا — اكتب رقم الباركود');try{WCS=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const v=$('#wsVd'),d=new BarcodeDetector();v.srcObject=WCS;let last='',lt=0;const lp=async()=>{if(!WCS)return;try{const r=await d.detect(v);if(r[0]){const c=r[0].rawValue,n=Date.now();if(c!==last||n-lt>1800){last=c;lt=n;const p=D.p.find(x=>bcEq(x,c));if(p){wsAdd(p.id);navigator.vibrate?.(40)}else{beep(false);tz('باركود غير معروف: '+c)}}}}catch(x){}setTimeout(lp,200)};lp()}catch(x){tz('تعذر فتح الكاميرا — اسمح بالوصول إليها')}}
