function wsSave(paid){const k=wsCalc(),c=D.c.find(x=>x.id==WCU);if(!WS.length)return tz('الفاتورة فارغة');paid=Math.max(0,+paid||0);if(paid<k.net&&!c)return tz('اختر عميلًا لتسجيل المتبقي (بيع آجل)');const i={id:D.seq++,t:new Date().toISOString(),cid:c?c.id:'',cust:c?c.n:'',lines:WS.map(l=>({...l})),sub:k.sub,disc:k.ds,tax:k.tax,net:k.net,paid,pay:'نقدي',mode:WM,by:ME?ME.n:'',role:ME?ME.role:'',pb:c?cbal(c):0,st:'ok'};WS.forEach(l=>{const p=gp(l.pid);if(p&&!p.ul){p.q-=l.qty;consume(p,l.qty)}});if(c){c.bought+=k.net;c.paid+=Math.min(paid,k.net)}D.inv.push(i);save();wsClose();showInv(i.id)}
