const idb=new Promise(res=>{try{const r=indexedDB.open('obb_imgs',1);r.onupgradeneeded=()=>r.result.createObjectStore('i');r.onsuccess=()=>res(r.result);r.onerror=()=>res(null);r.onblocked=()=>res(null)}catch(x){res(null)}});
