function getImg(f){if(!f)return;if(!f.type.startsWith('image/'))return tz('اختر ملف صورة');const u=URL.createObjectURL(f),im=new Image;im.onerror=()=>{URL.revokeObjectURL(u);tz('تعذر فتح هذه الصورة، جرّب صيغة JPG أو PNG')};im.onload=()=>{OF=f;startCrop(im,f)};im.src=u}
