function crot(){const[iw,ih]=isz(CR.im),c=document.createElement('canvas');c.width=ih;c.height=iw;const g=c.getContext('2d');g.translate(ih,0);g.rotate(Math.PI/2);g.drawImage(CR.im,0,0);CR.im=c;CR.rot=true;CR.x=CR.y=0;cdraw()}
async function capply(){const{im,w,h}=CR,[iw,ih]=isz(im),s=Math.max(w/iw,h/ih)*CR.z,dx=(w-iw*s)/2+CR.x,dy=(h-ih*s)/2+CR.y,sx=Math.max(0,-dx/s),sy=Math.max(0,-dy/s),sw=Math.min(iw-sx,w/s),sh=Math.min(ih-sy,h/s);md();tz('جارٍ معالجة الصورة...');await finishImg(im,sx,sy,sw,sh,null);TAR=null;OI=im;pv();tz('تم قص الصورة بالجودة الكاملة')}
