/* saving files */
async function saveFile(name,text,mime){let dl=null;try{dl=await window.claude?.use('downloads')}catch(x){}
if(dl){try{await dl.save({filename:name,data:text});return 1}catch(x){if(x&&x.code=='declined')return -1}}
try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime||'application/octet-stream'}));a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},4000);return 1}catch(x){return 0}}
async function shareFile(name,text,mime){try{const f=new File([text],name,{type:mime});if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f],title:name});return 1}}catch(x){if(x&&x.name=='AbortError')return -1}return 0}
function copyBox(t,text,cb){md(`<h3 class="font-bold mb-2">${t}</h3><p class="text-sm text-gray-600 mb-2">التنزيل المباشر غير متاح هنا. انسخ النص كله واحفظه في ملف أو في ملاحظاتك.</p><textarea id="bk" readonly rows="8" class="ip" style="min-height:160px;font-size:11px" onclick="this.select()">${e(text)}</textarea><div class="flex gap-2 mt-3"><button class="bt bg1" onclick="$('#bk').select();document.execCommand('copy');tz('تم النسخ')${cb?';('+cb+')()':''}">نسخ</button><button class="bt" onclick="md()">إغلاق</button></div>`,'max-w-2xl')}
function prodInfo(){const l=D.set.lpx||0,ch=D.p.filter(p=>(p.u||p.t||0)>l).length,el=$('#prodSaveInfo');if(!el)return;el.innerHTML=`<b>${D.p.length}</b> منتج — `+(l?`آخر حفظ لملف المنتجات: ${new Date(l).toLocaleDateString('ar-EG')} · `+(ch?`<span class="text-amber-700 font-bold">${ch} منتج جديد أو معدّل بعد آخر حفظ</span>`:'<span class="text-emerald-700 font-bold">كل التعديلات محفوظة في الملف</span>'):'<span class="text-rose-600 font-bold">لم تحفظ ملف المنتجات بعد</span>')}
function exportProducts(){md(`<h3 class="font-bold mb-1">حفظ المنتجات</h3><p class="text-sm text-gray-600 mb-3">${D.p.length} منتج بأسعارها وأقسامها وكمياتها. احفظ الملف خارج التطبيق (التنزيلات أو Drive أو واتساب)، وبه تستعيد منتجاتك حتى لو حذفت التطبيق أو مسحت بياناته. الصور داخل الملف بجودة الويب (640px)، أما الصور الأصلية فتبقى محفوظة على هذا الجهاز.</p><div class="grid gap-2"><button class="bt bg1 flex items-center justify-center gap-2" onclick="doExp('json')">${ic('download','w-5 h-5')}ملف كامل مع الصور (JSON)</button><button class="bt flex items-center justify-center gap-2" onclick="doExp('csv')">${ic('file','w-5 h-5')}جدول Excel بدون صور (CSV)</button><button class="bt flex items-center justify-center gap-2" onclick="doExp('share')">${ic('share','w-5 h-5')}مشاركة / حفظ في Drive أو واتساب</button><button class="bt" onclick="md()">إغلاق</button></div>`)}
async function doExp(k){const d=ld(new Date()),csv=()=>'\ufeff'+['الاسم,الباركود,القسم,سعر الشراء,سعر الجملة,سعر البيع,الكمية,حد التنبيه',...D.p.map(p=>['"'+String(p.n).replace(/"/g,'""')+'"','"'+(p.bc||'')+'"','"'+String(p.cat||'').replace(/"/g,'""')+'"',p.buy,p.whs||0,p.sell,p.q,p.min].join(','))].join('\n'),
js=()=>JSON.stringify({app:'obb-products',v:1,date:new Date().toISOString(),cats:D.cats,products:D.p});
let r,txt,nm;if(k=='csv'){nm='products-'+d+'.csv';txt=csv();r=await saveFile(nm,txt,'text/csv')}else{nm='products-'+d+'.json';txt=js();r=k=='share'?await shareFile(nm,txt,'application/json'):await saveFile(nm,txt,'application/json');if(k=='share'&&r===0)r=await saveFile(nm,txt,'application/json')}
if(r<0)return;if(r===0){copyBox('ملف المنتجات',txt,'()=>{D.set.lpx=Date.now();save();prodInfo()}');return}
D.set.lpx=Date.now();save();prodInfo();md();tz('تم حفظ ملف المنتجات')}
function parseCsv(t){const rows=[];let r=[],c='',q=false;for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch=='"'){if(t[i+1]=='"'){c+='"';i++}else q=false}else c+=ch}else if(ch=='"')q=true;else if(ch==','||ch==';'){r.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;r.push(c);rows.push(r);r=[];c=''}else c+=ch}if(c||r.length){r.push(c);rows.push(r)}
const H={'الاسم':'n','الباركود':'bc','القسم':'cat','سعر الشراء':'buy','سعر الجملة':'whs','سعر البيع':'sell','الكمية':'q','حد التنبيه':'min'},hd=rows.shift().map(x=>H[x.trim()]);return rows.filter(r=>r.some(x=>x.trim())).map(r=>{const o={};hd.forEach((k,i)=>{if(k)o[k]=(r[i]||'').trim()});return o})}
function importProducts(ev){const fl=ev.target.files[0];ev.target.value='';if(!fl)return;const r=new FileReader;r.onerror=()=>tz('تعذر قراءة الملف');r.onload=()=>{try{const t=String(r.result).replace(/^\ufeff/,'').trim();let arr,cats=[];if(t[0]=='{'||t[0]=='['){const j=JSON.parse(t);arr=Array.isArray(j)?j:j.products;cats=j.cats||[]}else arr=parseCsv(t);if(!Array.isArray(arr)||!arr.length)throw 0;mergeProducts(arr,cats)}catch(x){tz('الملف غير صالح — اختر ملف المنتجات الذي حفظته من التطبيق')}};r.readAsText(fl)}
function mergeProducts(arr,cats){let add=0,upd=0;(cats||[]).forEach(c=>{if(c&&!D.cats.includes(c))D.cats.push(c)});
arr.forEach(x=>{const n=String(x.n||'').trim();if(!n)return;const o={n,bc:String(x.bc||'').trim(),cat:String(x.cat||'').trim()||D.cats[D.cats.length-1]||'',buy:+x.buy||0,whs:+x.whs||0,sell:+x.sell||0,q:+x.q||0,min:+x.min||0};if(x.im)o.im=x.im;if(x.ul)o.ul=1;if(x.ar)o.ar=x.ar;if(x.old>0)o.old=+x.old;if(x.fv)o.fv=1;if(Array.isArray(x.bt))o.bt=x.bt;if(o.cat&&!D.cats.includes(o.cat))D.cats.push(o.cat);
const p=D.p.find(y=>(x.id&&y.id==x.id)||(o.bc&&y.bc==o.bc)||(!o.bc&&y.n==n));if(p){Object.assign(p,o,{u:Date.now()});upd++}else{D.p.push({id:x.id&&!D.p.some(y=>y.id==x.id)?x.id:U(),t:Date.now()+add,u:Date.now(),...o});add++}});
save();rProd();tz(`تم الاستيراد: أُضيف ${add} منتج وحُدّث ${upd}`)}
