const latin1=u=>{let s='';for(let i=0;i<u.length;i++)s+=String.fromCharCode(u[i]);return s},
dec8=(u,cp)=>{try{return new TextDecoder('windows-'+cp).decode(u)}catch(x){return latin1(u)}},
fnum=v=>String(parseFloat((+v).toPrecision(15))),
isNumStr=x=>{x=String(x).trim();return /^[\d.,٠-٩۰-۹٫٬\s()+-]+$/.test(x)&&/[\d٠-٩۰-۹]/.test(x)},
nz=s=>norm(String(s==null?'':s)).replace(/[:：*()\[\]_\-\/\\.]/g,' ').replace(/\s+/g,' ').trim();
function decodeText(buf){const u=new Uint8Array(buf);if(u[0]==0xEF&&u[1]==0xBB&&u[2]==0xBF)return new TextDecoder('utf-8').decode(u.subarray(3));if(u[0]==0xFF&&u[1]==0xFE)return new TextDecoder('utf-16le').decode(u.subarray(2));if(u[0]==0xFE&&u[1]==0xFF)return new TextDecoder('utf-16be').decode(u.subarray(2));try{return new TextDecoder('utf-8',{fatal:true}).decode(u)}catch(x){try{return new TextDecoder('windows-1256').decode(u)}catch(y){return latin1(u)}}}
function detectDelim(t){const L=t.split(/\r?\n/).filter(x=>x.trim()).slice(0,8);let best=',',bs=0;for(const d of ['\t',';',',','|']){const cs=L.map(l=>{let q=false,c=0;for(const ch of l){if(ch=='"')q=!q;else if(!q&&ch==d)c++}return c});const mn=Math.min(...cs),av=cs.reduce((a,b)=>a+b,0)/(cs.length||1),sc=mn>0?mn*10+av:av/10;if(sc>bs){bs=sc;best=d}}return best}
function parseDelim(t,d){const rows=[];let r=[],c='',q=false;const n=t.length;for(let i=0;i<n;i++){const ch=t[i];if(q){if(ch=='"'){if(t[i+1]=='"'){c+='"';i++}else q=false}else c+=ch}else if(ch=='"'&&c==='')q=true;else if(ch==d){r.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;r.push(c);rows.push(r);r=[];c=''}else c+=ch}if(c!==''||r.length){r.push(c);rows.push(r)}return rows}
function readHtml(t){const d=new DOMParser().parseFromString(t,'text/html'),tb=[...d.querySelectorAll('table')];if(!tb.length)throw 0;const rowsOf=x=>[...x.querySelectorAll('tr')].filter(tr=>tr.closest('table')===x).map(tr=>[...tr.children].filter(c=>/^t[dh]$/i.test(c.tagName)).map(c=>c.textContent.replace(/\s+/g,' ').trim()));const all=tb.map(rowsOf);all.sort((a,b)=>b.length-a.length);return all[0]}
function readXml2003(t){const d=new DOMParser().parseFromString(t,'text/xml'),out=[];for(const ws of d.getElementsByTagNameNS('*','Worksheet')){const rows=[];for(const tr of ws.getElementsByTagNameNS('*','Row')){const r=[];let ci=0;for(const c of tr.getElementsByTagNameNS('*','Cell')){const ix=c.getAttribute('ss:Index')||c.getAttributeNS('urn:schemas-microsoft-com:office:spreadsheet','Index');if(ix)ci=+ix-1;const dt=c.getElementsByTagNameNS('*','Data')[0];r[ci++]=dt?dt.textContent:''}rows.push(r)}out.push({name:ws.getAttribute('ss:Name')||'Sheet',rows})}return out}
/* --- zip + xlsx + ods --- */
async function inflate(u8){const ds=new DecompressionStream('deflate-raw'),w=ds.writable.getWriter();w.write(u8);w.close();return new Uint8Array(await new Response(ds.readable).arrayBuffer())}
async function unzip(buf){const u=new Uint8Array(buf),dv=new DataView(buf);let e=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65557);i--){if(dv.getUint32(i,true)==0x06054b50){e=i;break}}if(e<0)throw 0;const n=dv.getUint16(e+10,true);let p=dv.getUint32(e+16,true);const files={};for(let k=0;k<n;k++){if(dv.getUint32(p,true)!=0x02014b50)break;const meth=dv.getUint16(p+10,true),csz=dv.getUint32(p+20,true),nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),off=dv.getUint32(p+42,true),name=new TextDecoder().decode(u.subarray(p+46,p+46+nl));files[name]={meth,csz,off};p+=46+nl+el+cl}
return{files,async get(name){const f=files[name];if(!f)return null;const lh=f.off,nl=dv.getUint16(lh+26,true),el=dv.getUint16(lh+28,true),ds=lh+30+nl+el,data=u.subarray(ds,ds+f.csz);return f.meth==0?data:await inflate(data)}}}
function parseSheetXml(d,ss){const rows=[],ci=r=>{let n=0;for(const ch of r.replace(/\d/g,''))n=n*26+ch.charCodeAt(0)-64;return n-1};
for(const row of d.getElementsByTagNameNS('*','row')){const ri=(+row.getAttribute('r')||rows.length+1)-1,arr=rows[ri]=rows[ri]||[];let last=-1;for(const c of row.getElementsByTagNameNS('*','c')){const ref=c.getAttribute('r'),col=ref?ci(ref):last+1;last=col;const t=c.getAttribute('t'),vEl=c.getElementsByTagNameNS('*','v')[0];let v='';if(t=='inlineStr')v=[...c.getElementsByTagNameNS('*','t')].map(x=>x.textContent).join('');else if(vEl){const raw=vEl.textContent;if(t=='s')v=ss[+raw]==null?'':ss[+raw];else if(t=='b')v=raw=='1'?'1':'0';else if(t=='e')v='';else if(t=='str')v=raw;else v=raw.length>15||/e/i.test(raw)?fnum(+raw):raw}if(v!=='')arr[col]=v}}return rows}
