/* --- screens --- */
function openImport(){md(`<h3 class="font-bold mb-1">استيراد منتجات</h3><p class="text-xs text-gray-600 mb-3">من أي برنامج: ملف Excel (xlsx / xls) أو CSV أو جدول HTML أو XML أو ODS، أو الصق الخلايا مباشرة. يتعرّف التطبيق تلقائيًا على الأعمدة ويمكنك تعديلها قبل الاستيراد.</p><label class="bt bg1 flex items-center justify-center gap-2 cursor-pointer w-full">${ic('upload','w-5 h-5')}اختيار ملف<input id="impF" type="file" class="hidden" onchange="impFile(this)"></label><div class="text-xs text-gray-500 text-center my-2">أو الصق الخلايا هنا</div><textarea id="impTx" rows="4" class="ip" style="min-height:90px" placeholder="انسخ الخلايا من Excel أو Google Sheets مع صف العناوين ثم الصقها هنا"></textarea><div class="flex gap-2 mt-2"><button class="bt flex-1" onclick="impPaste()">قراءة النص الملصوق</button><button class="bt flex-1" onclick="impTemplate()">تحميل نموذج</button></div><button class="bt w-full mt-2" onclick="md()">إغلاق</button>`)}
async function impTemplate(){const t='\ufeff'+'اسم المنتج,الباركود,القسم,سعر الشراء,سعر الجملة,سعر البيع,الكمية,حد التنبيه\n'+'كريم أساس 50 مل,6221234567890,مستحضرات التجميل,60,80,100,24,5\n'+'شامبو للشعر 400 مل,6220000000017,العناية الشخصية,35,45,60,12,3\n',r=await saveFile('products-template.csv',t,'text/csv');if(r==0)copyBox('نموذج المنتجات',t,'')}
function impPaste(){const t=($('#impTx').value||'').trim();if(!t)return tz('الصق البيانات أولًا');try{const x=t.replace(/^sep=.\r?\n/,'');impStart({sheets:[{name:'مُلصق',rows:parseDelim(x,detectDelim(x))}]},'نص ملصوق')}catch(x){tz('تعذّرت قراءة النص الملصوق')}}
async function impFile(el){const f=el.files[0];el.value='';if(!f)return;tz('جارٍ قراءة الملف...');try{const R=await readAny(await f.arrayBuffer(),f.name);if(R.done){md();return}impStart(R,f.name)}catch(x){console.error(x);const nodc=typeof DecompressionStream=='undefined'&&/\.(xlsx|xlsm|ods)$/i.test(f.name);md(`<h3 class="font-bold mb-2">تعذّرت قراءة الملف</h3><p class="text-sm text-gray-700 mb-2">${nodc?'هذا المتصفح لا يدعم فك ضغط ملفات Excel الحديثة. افتح الملف في Excel واحفظه بصيغة <b>CSV (UTF-8)</b> ثم أعد الاستيراد، أو حدّث المتصفح.':'الصيغ المدعومة: Excel (xlsx / xls) و CSV و TSV و جداول HTML و XML و ODS و JSON. إن كان الملف محميًا بكلمة سر أو بصيغة أخرى فاحفظه من البرنامج بصيغة Excel أو CSV (UTF-8) ثم أعد المحاولة.'}</p><p class="text-xs text-gray-500 mb-3" dir="ltr">${e(f.name)} · ${Math.round(f.size/1024)} KB</p><button class="bt bg1 w-full" onclick="openImport()">محاولة ملف آخر</button>`)}}
function impNorm(rows){let z=rows.length;while(z>0&&(!rows[z-1]||rows[z-1].every(x=>x==null||String(x).trim()==='')))z--;rows=rows.slice(0,z);const w=rows.reduce((m,r)=>{if(!r)return m;let k=r.length;while(k>m&&(r[k-1]==null||String(r[k-1]).trim()===''))k--;return Math.max(m,k)},0),out=Array.from({length:rows.length},(_,i)=>{const r=rows[i];return Array.from({length:w},(_,c)=>{const v=r?r[c]:'';return v==null?'':String(v).trim()})});while(out.length&&out[out.length-1].every(x=>x===''))out.pop();return out}
