function impSheet(i){const I=IM;I.si=i;I.rows=I.sheets[i].rows;I.width=I.rows[0]?I.rows[0].length:0;I.hdr=detectHdr(I.rows);I.map=autoMap(I.rows,I.hdr,I.width);impUI()}
function impHdr(h){IM.hdr=h;IM.map=autoMap(IM.rows,h,IM.width);impUI()}
function impMap(f,c){IM.map[f]=c;impPrev()}
function impUI(){const I=IM,o=I.opt,cn=c=>{const h=I.hdr>=0?I.rows[I.hdr][c]:'',ex=(I.rows[I.hdr+1]||[])[c];return`${c+1}. ${h||'(بدون عنوان)'}${ex?' — '+String(ex).slice(0,14):''}`},co=sel=>`<option value="-1">— لا يوجد —</option>`+Array.from({length:I.width},(_,c)=>`<option value="${c}" ${sel==c?'selected':''}>${e(cn(c))}</option>`).join('');
md(`<h3 class="font-bold">استيراد منتجات</h3><p class="text-xs text-gray-600 mb-2" dir="auto">${e(I.fileName)} — ${I.rows.length} صف</p>${I.sheets.length>1?`<label class="text-xs text-gray-600 block mb-2">ورقة العمل<select class="ip" onchange="impSheet(+this.value)">${I.sheets.map((s,k)=>`<option value="${k}" ${I.si==k?'selected':''}>${e(s.name)} (${s.rows.length} صف)</option>`).join('')}</select></label>`:''}
<label class="text-xs text-gray-600 block mb-2">صف العناوين<select class="ip" onchange="impHdr(+this.value)"><option value="-1" ${I.hdr<0?'selected':''}>لا يوجد صف عناوين</option>${Array.from({length:Math.min(I.rows.length,30)},(_,r)=>`<option value="${r}" ${I.hdr==r?'selected':''}>${r+1}: ${e(I.rows[r].filter(Boolean).slice(0,4).join(' | ').slice(0,40))}</option>`).join('')}</select></label>
<div class="grid grid-cols-1 sm:grid-cols-2 gap-2">${IMF.map(([f,l])=>`<label class="text-xs text-gray-600 block">${l}<select class="ip" onchange="impMap('${f}',+this.value)">${co(I.map[f])}</select></label>`).join('')}</div>
<div class="mt-3 space-y-2 text-sm"><label class="flex items-center gap-2"><input type="checkbox" class="w-5 h-5" ${o.upd?'checked':''} onchange="IM.opt.upd=this.checked;impPrev()">تحديث أسعار المنتجات الموجودة عند تغيّرها فقط (لا يُكرَّر المنتج)</label><label class="flex items-center gap-2"><input type="checkbox" class="w-5 h-5" ${o.newCats?'checked':''} onchange="IM.opt.newCats=this.checked">إنشاء الأقسام الجديدة تلقائيًا</label><label class="text-xs text-gray-600 block">الكمية<select class="ip" onchange="IM.opt.qmode=this.value"><option value="set" ${o.qmode=='set'?'selected':''}>استبدال الكمية الحالية بالكمية في الملف</option><option value="add" ${o.qmode=='add'?'selected':''}>إضافة كمية الملف إلى الكمية الحالية</option><option value="ignore" ${o.qmode=='ignore'?'selected':''}>تجاهل الكمية</option></select></label></div>
<div id="impPrev"></div><div class="flex gap-2 mt-3"><button id="impGo" class="bt bg1 flex-1" onclick="impRun()">استيراد الآن</button><button class="bt flex-1" onclick="md()">إلغاء</button></div>`,'max-w-2xl');impPrev()}
var IMX=null;function impIdx(){const bc=new Set(),n=new Set();D.p.forEach(p=>{if(p.bc)bc.add(String(p.bc).replace(/\s+/g,'').toUpperCase());n.add(norm(p.n))});IMX={bc,n}}
function impExists(it){if(!IMX)impIdx();return!!((it.bc&&IMX.bc.has(it.bc.toUpperCase()))||IMX.n.has(norm(it.n)))}
function impPrev(){const el=$('#impPrev'),I=IM;if(!el)return;if(I.map.n<0){el.innerHTML='<p class="text-sm text-rose-600 mt-3">اختر عمود «اسم المنتج» أولًا.</p>';$('#impGo').disabled=true;return}
impIdx();const{items,issues,st}=impConv(),nu=items.filter(it=>!impExists(it)).length,f2=x=>x==null?'':x;
el.innerHTML=`<div class="mt-3 text-sm"><b>${items.length}</b> منتج صالح — <span class="text-emerald-700">${nu} جديد</span> · ${items.length-nu} موجود${st.dup?` · ${st.dup} مكرر داخل الملف (يُدمج)`:''}${st.noname?` · ${st.noname} صف بلا اسم`:''}</div><div class="overflow-auto mt-2 border border-beige-200 rounded-xl"><table class="w-full text-xs"><thead class="bg-beige-100"><tr>${['الاسم','الباركود','القسم','البيع','الشراء','الكمية','الحالة'].map(h=>`<th class="p-2 text-right whitespace-nowrap">${h}</th>`).join('')}</tr></thead><tbody>${items.slice(0,6).map(it=>`<tr class="border-t border-beige-100"><td class="p-2">${e(it.n)}</td><td class="p-2" dir="ltr">${e(it.bc)}</td><td class="p-2">${e(it.cat)}</td><td class="p-2">${f2(it.sell)}</td><td class="p-2">${f2(it.buy)}</td><td class="p-2">${f2(it.q)}</td><td class="p-2 whitespace-nowrap">${impExists(it)?'موجود':'جديد'}</td></tr>`).join('')}</tbody></table></div>${items.length>6?`<p class="text-xs text-gray-500 mt-1">… و${items.length-6} منتج آخر</p>`:''}${issues.length?`<details class="mt-2 text-xs text-amber-700"><summary>${issues.length>=60?'60+':issues.length} ملاحظة على بعض الصفوف</summary><ul class="list-disc pr-5 mt-1 space-y-0.5">${issues.slice(0,15).map(x=>`<li>${e(x)}</li>`).join('')}</ul></details>`:''}`;$('#impGo').disabled=!items.length}
function impRun(){const{items,issues,st}=impConv(),o=IM.opt;if(!items.length)return tz('لا توجد صفوف صالحة للاستيراد');
IMUNDO={p:JSON.stringify(D.p),cats:[...D.cats]};const byBc=new Map(),byN=new Map(),key=b=>String(b).replace(/\s+/g,'').toUpperCase();D.p.forEach(p=>{if(p.bc)byBc.set(key(p.bc),p);byN.set(norm(p.n),p)});
let add=0,upd=0,skip=0,nc=0;const dc=D.cats[D.cats.length-1]||'أخرى',now=Date.now();if(!D.cats.length)D.cats.push(dc);
items.forEach((it,k)=>{const p=(it.bc&&byBc.get(key(it.bc)))||byN.get(norm(it.n))||null;let cat=it.cat;if(cat&&!D.cats.includes(cat)){if(o.newCats){D.cats.push(cat);nc++}else cat=''}
if(p){if(!o.upd){skip++;return}let ch=false;for(const f of ['sell','buy','whs','old'])if(it[f]!=null&&Math.abs((+p[f]||0)-it[f])>0.0005){p[f]=it[f];ch=true}if(p.old<=0)delete p.old;if(!ch){skip++;return}p.u=now;upd++}
else{const np={id:U(),t:now+k,u:now,n:it.n,bc:it.bc||'',cat:cat||dc,buy:it.buy||0,whs:it.whs||0,sell:it.sell||0,q:o.qmode=='ignore'?0:(it.q||0),ul:(o.qmode!='ignore'&&it.q==null)?1:0,min:it.min!=null?it.min:5};if(it.old>0)np.old=it.old;D.p.push(np);if(np.bc)byBc.set(key(np.bc),np);byN.set(norm(np.n),np);add++}});
save();rProd();const box=(n,l,c)=>`<div class="rounded-xl p-2 ${c}"><div class="text-xl font-extrabold">${n}</div><div class="text-xs">${l}</div></div>`;
md(`<h3 class="font-bold mb-2">تم الاستيراد</h3><div class="grid grid-cols-2 gap-2 text-center">${box(add,'منتج جديد','bg-emerald-50 text-emerald-800')}${box(upd,'تحديث أسعار','bg-beige-100')}${box(skip+st.noname,'موجود بدون تغيير','bg-beige-100')}${box(st.dup,'مكرر دُمج','bg-beige-100')}</div>${nc?`<p class="text-xs text-gray-600 mt-2">أقسام جديدة: ${nc}</p>`:''}${issues.length?`<details class="mt-2 text-xs text-amber-700"><summary>${issues.length>=60?'60+':issues.length} ملاحظة</summary><ul class="list-disc pr-5 mt-1 space-y-0.5 max-h-40 overflow-auto">${issues.slice(0,40).map(x=>`<li>${e(x)}</li>`).join('')}</ul></details>`:''}<div class="flex gap-2 mt-3"><button class="bt flex-1" onclick="impUndo()">تراجع عن الاستيراد</button><button class="bt bg1 flex-1" onclick="md()">تم</button></div>`)}
function impUndo(){if(!IMUNDO)return tz('لا يوجد ما يُتراجع عنه');D.p=JSON.parse(IMUNDO.p);D.cats=IMUNDO.cats;IMUNDO=null;save();rProd();md();tz('تم التراجع عن الاستيراد')}

/* backup */
async function exportJSONBackup(){const txt=JSON.stringify(D),r=await saveFile('obb-backup-'+ld(new Date())+'.json',txt,'application/json');if(r<0)return;if(r){D.lb=Date.now();save();info();tz('تم تنزيل النسخة الاحتياطية');return}copyBox('النسخة الاحتياطية',txt,'()=>{D.lb=Date.now();save()}')}
async function exportCSV(){const t='\ufeff'+['رقم,التاريخ,العميل,الصافي,المدفوع,الدفع,الحالة',...D.inv.map(i=>[i.id,ld(i.t),'"'+(i.cust||'').replace(/"/g,'""')+'"',i.net,i.paid,i.pay,i.st=='x'?'ملغاة':'ساري'].join(','))].join('\n'),r=await saveFile('invoices-'+ld(new Date())+'.csv',t,'text/csv');if(r<0||r)return;copyBox('الفواتير CSV',t)}
function applyBackup(t){try{const d=JSON.parse(t);if(!Array.isArray(d.p))throw 0;const op=D.set.ph,orc=D.set.rc;D=d;if(d.set&&!d.set.ph&&op){d.set.ph=op;d.set.rc=orc}D.set=D.set||{name:'مكتبة أولاد بلال',phone:'',addr:'',fmt:'thermal'};D.c=D.c||[];D.ex=D.ex||[];D.pm=D.pm||[];D.rt=D.rt||[];D.rn=D.rn||[];D.sp=D.sp||[];D.pu=D.pu||[];D.sy=D.sy||[];D.mg=D.mg||[];save();switchTab(tab);tz('تمت الاستعادة')}catch(x){tz('ملف غير صالح')}}
function importJSONBackup(ev){const fl=ev.target.files[0];if(!fl)return;const r=new FileReader;r.onload=()=>applyBackup(r.result);r.readAsText(fl)}
function pasteRestore(){md(`<h3 class="font-bold mb-2">الصق النسخة الاحتياطية</h3><textarea id="rt" rows="8" class="ip" style="min-height:160px"></textarea><div class="flex gap-2 mt-3"><button class="bt bg1" onclick="applyBackup($('#rt').value);md()">استعادة</button><button class="bt" onclick="md()">إلغاء</button></div>`,'max-w-2xl')}
/* numeric + search inputs: accept Arabic/Persian digits and separators, friendly keyboards */
const cleanNum=(v,sg)=>{let s=String(v).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٫,،]/g,'.').replace(/[−–—]/g,'-'),neg=sg&&/^\s*-/.test(s);s=s.replace(/[^\d.]/g,'');const i=s.indexOf('.');if(i>=0)s=s.slice(0,i+1)+s.slice(i+1).replace(/\./g,'');return(neg?'-':'')+s};
document.addEventListener('input',ev=>{const t=ev.target;if(t&&t.dataset&&t.dataset.num!==undefined){const c=cleanNum(t.value,t.dataset.num=='s');if(c!==t.value){const p=t.selectionStart;t.value=c;try{t.setSelectionRange(p,p)}catch(x){}}}},true);
const SRCH=['storeSearchInput','posQ','globalSearch','prodQ','invS','custQ','invQ','lbQ','puQ','rtQ','fgCode'];
function fixNums(){document.querySelectorAll('input[type=number]').forEach(el=>{el.type='text';el.dataset.num='';if(!el.getAttribute('inputmode'))el.setAttribute('inputmode','decimal');el.setAttribute('autocomplete','off')});SRCH.forEach(id=>{const el=document.getElementById(id);if(el&&!el.dataset.sx){el.dataset.sx=1;el.type=id=='fgCode'?'text':'search';el.setAttribute('inputmode',id=='fgCode'?'numeric':'search');el.setAttribute('enterkeyhint','search');el.setAttribute('autocomplete','off');el.setAttribute('autocapitalize','off');el.setAttribute('spellcheck','false')}})}
const lbl=()=>document.querySelectorAll('.tbl').forEach(t=>{const h=[...t.rows[0].cells].map(c=>c.textContent.trim());[...t.rows].slice(1).forEach(r=>[...r.cells].forEach((c,i)=>c.dataset.l=h[i]||''))});new MutationObserver(()=>requestAnimationFrame(()=>{lbl();fixNums()})).observe(document.body,{childList:true,subtree:true});
navigator.storage?.persist?.();loadImgs();
hydrate();badge();applyTheme();fixNums();
(async()=>{try{DB=await window.claude?.use('db')}catch(x){DB=null}if(DB){setSt('busy');listen();setTimeout(bootLock,2500)}else{setSt('local');bootLock()}})();

/* Cairo font: loads from Google when online, then keeps a copy on the device so it also works offline */
(function(){const KF='obb_font_v1',URL_='https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&display=swap';
try{if(localStorage.getItem(KF)||!navigator.onLine)return}catch(x){return}
const l=document.createElement('link');l.rel='stylesheet';l.href=URL_;document.head.appendChild(l);
(async()=>{try{const t=await (await fetch(URL_)).text(),bl=[...t.matchAll(/\/\*\s*([\w-]+)\s*\*\/\s*(@font-face\s*\{[^}]*\})/g)].filter(m=>m[1]=='arabic'||m[1]=='latin');if(!bl.length)return;let out='';
for(const m of bl){let b=m[2];const u=b.match(/url\((https:[^)]+)\)/)[1],a=new Uint8Array(await (await fetch(u)).arrayBuffer());let bin='';for(let i=0;i<a.length;i+=0x8000)bin+=String.fromCharCode.apply(null,a.subarray(i,i+0x8000));b=b.replace(/src:[^;]*;/,'src:url(data:font/woff2;base64,'+btoa(bin)+') format("woff2");');out+=b+'\n'}
localStorage.setItem(KF,out)}catch(x){}})()})();
